window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7c82f5e742aaea65"]={"versions": [{"id": "FIG-7c82f5e742aaea65", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur für Ausführungsbedingungen (<code>ExecutionConstraints</code>) im Rahmen der AUTOSAR-Interaktion mit Verhaltensmodellen (<code>AUTOSAR_TR_InteractionWithBehavioralModels</code>). Das Diagramm verknüpft das externe Paket <code>BM Environment</code> (aus <code>Behavior Modeling</code>) über Import-Abhängigkeiten (<code>«import»</code>) mit den Klassen des Metamodells für Runnable-Ausführungsbedingungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutionConstraints::RunnableExecutionConstraint</code></strong>: Zentrales Wurzelelement des Constraint-Modells. Es aggregiert mittels Komposition (<code><em></code>) eine Menge von beobachtbaren Elementen (<code>+observables: ExecutionConstraints::Observable [</em>]</code>) sowie genau ein Ausführungsverhalten (<code>+behavior: ExecutionConstraints::Behavior [1]</code>).</li>\n<li><strong><code>ExecutionConstraints::Observable</code></strong>: Abstrakte bzw. identifizierbare Entität (stereotypisiert als <code>Identifiable</code>), die über <code>«import»</code> aus der Modellumgebung importiert werden kann.</li>\n<li><strong><code>ExecutionConstraints::Behavior</code></strong>: Abstrakte Basisklasse für Ausführungsverhalten, die eine geordnete Referenzliste auf beobachtbare Instanzen über das Stereotyp <code>«atpInstanceRef»</code> / <code>«InstanceRef»</code> hält (<code>+observables / <em>: ExecutionConstraints::Observable [</em>] {ordered}</code>).</li>\n<li><strong><code>ExecutionConstraints::AllowedBehavior</code></strong> und <strong><code>ExecutionConstraints::NotAllowedBehavior</code></strong>: Konkrete Spezialisierungen (Generalisierungsbeziehung), die von <code>ExecutionConstraints::Behavior</code> erben und zulässige bzw. unzulässige Ausführungssequenzen repräsentieren.</li>\n<li><strong><code>BM Environment</code> (from Behavior Modeling)</strong>: Paketkontext, aus dem <code>RunnableExecutionConstraint</code>, <code>Observable</code>, <code>Behavior</code>, <code>NotAllowedBehavior</code> und <code>AllowedBehavior</code> importiert werden (<code>«import»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Nachrichtensequenzen. Die dynamische Semantik wird deklarativ modelliert: Ein <code>RunnableExecutionConstraint</code> definiert ein Ausführungsreglement für Runnables, indem es ein Soll- oder Ausschlussmuster (<code>AllowedBehavior</code> vs. <code>NotAllowedBehavior</code>) mit einer geordneten Sequenz (<code>{ordered}</code>) beobachtbarer Instanzen (<code>Observable</code>) verknüpft. Werkzeuge zur Verhaltensanalyse prüfen zur Laufzeit oder in der Simulation, ob die Abfolge der beobachtbaren Ereignisse der vorgegebenen Constraint-Definition entspricht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Spezifikation für AUTOSAR-Entwicklungswerkzeuge zur Modellierung von Verhaltensrestriktionen und Timing-/Ausführungsbedingungen von Runnable Entities. Werkzeughersteller müssen die Instanzreferenzen (<code>«InstanceRef»</code>) auf beobachtbare Elemente korrekt serialisieren, die Ordnung (<code>{ordered}</code>) der Observables in Verhaltenselementen wahren und zwischen positiven (<code>AllowedBehavior</code>) sowie negativen (<code>NotAllowedBehavior</code>) Constraints differenzieren.</p>"}, {"id": "FIG-32e2d8bc4c1a43fa", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Struktur für Ausführungsbedingungen (<code>ExecutionConstraints</code>) im Rahmen der AUTOSAR-Interaktion mit Verhaltensmodellen (<code>AUTOSAR_TR_InteractionWithBehavioralModels</code>). Das Diagramm verknüpft das externe Paket <code>BM Environment</code> (aus <code>Behavior Modeling</code>) über Import-Abhängigkeiten (<code>«import»</code>) mit den Klassen des Metamodells für Runnable-Ausführungsbedingungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutionConstraints::RunnableExecutionConstraint</code></strong>: Zentrales Wurzelelement des Constraint-Modells. Es aggregiert mittels Komposition (<code><em></code>) eine Menge von beobachtbaren Elementen (<code>+observables: ExecutionConstraints::Observable [</em>]</code>) sowie genau ein Ausführungsverhalten (<code>+behavior: ExecutionConstraints::Behavior [1]</code>).</li>\n<li><strong><code>ExecutionConstraints::Observable</code></strong>: Abstrakte bzw. identifizierbare Entität (stereotypisiert als <code>Identifiable</code>), die über <code>«import»</code> aus der Modellumgebung importiert werden kann.</li>\n<li><strong><code>ExecutionConstraints::Behavior</code></strong>: Abstrakte Basisklasse für Ausführungsverhalten, die eine geordnete Referenzliste auf beobachtbare Instanzen über das Stereotyp <code>«atpInstanceRef»</code> / <code>«InstanceRef»</code> hält (<code>+observables / <em>: ExecutionConstraints::Observable [</em>] {ordered}</code>).</li>\n<li><strong><code>ExecutionConstraints::AllowedBehavior</code></strong> und <strong><code>ExecutionConstraints::NotAllowedBehavior</code></strong>: Konkrete Spezialisierungen (Generalisierungsbeziehung), die von <code>ExecutionConstraints::Behavior</code> erben und zulässige bzw. unzulässige Ausführungssequenzen repräsentieren.</li>\n<li><strong><code>BM Environment</code> (from Behavior Modeling)</strong>: Paketkontext, aus dem <code>RunnableExecutionConstraint</code>, <code>Observable</code>, <code>Behavior</code>, <code>NotAllowedBehavior</code> und <code>AllowedBehavior</code> importiert werden (<code>«import»</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Ablauf- oder Nachrichtensequenzen. Die dynamische Semantik wird deklarativ modelliert: Ein <code>RunnableExecutionConstraint</code> definiert ein Ausführungsreglement für Runnables, indem es ein Soll- oder Ausschlussmuster (<code>AllowedBehavior</code> vs. <code>NotAllowedBehavior</code>) mit einer geordneten Sequenz (<code>{ordered}</code>) beobachtbarer Instanzen (<code>Observable</code>) verknüpft. Werkzeuge zur Verhaltensanalyse prüfen zur Laufzeit oder in der Simulation, ob die Abfolge der beobachtbaren Ereignisse der vorgegebenen Constraint-Definition entspricht.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Spezifikation für AUTOSAR-Entwicklungswerkzeuge zur Modellierung von Verhaltensrestriktionen und Timing-/Ausführungsbedingungen von Runnable Entities. Werkzeughersteller müssen die Instanzreferenzen (<code>«InstanceRef»</code>) auf beobachtbare Elemente korrekt serialisieren, die Ordnung (<code>{ordered}</code>) der Observables in Verhaltenselementen wahren und zwischen positiven (<code>AllowedBehavior</code>) sowie negativen (<code>NotAllowedBehavior</code>) Constraints differenzieren.</p>"}], "trans": [{"from": "FIG-7c82f5e742aaea65", "to": "FIG-32e2d8bc4c1a43fa", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
